/* ── 骑行页 ────────────────────────────────────────────────────── */

/* 前方 2 km 海拔剖面。采样点数、段数、跳色阈值、三角填充 + 2px 脊线都
 * 沿用旧 UI（helm_shell.c 的 HELM_CLIMB_PROF_N / helm_climb_grade_zone /
 * helm_climb_paint_seg）。数据是**假数据**：按分段目标坡度累加，不是 GPX。 */
static double s_elev[ELEV_PROF_N];
static uint8_t s_elev_zone[ELEV_PROF_N - 1];
static uint8_t s_elev_cbuf[ELEV_CANVAS_W * ELEV_CANVAS_H * 2]
    __attribute__((aligned(4)));

/** 生成 2 km 假剖面：9 段不同坡度，保证灰/模式浅色/红三档都出现。 */
static void elev_profile_gen(void)
{
    /* n = 段数，pct = 该段坡度百分数；合计 59 段。 */
    static const struct {
        uint8_t n;
        double pct;
    } plan[] = {
        { 6, 0.5 },  /* 平路起步 */
        { 6, 2.6 },  /* 缓上（仍算平路） */
        { 6, 5.5 },  /* 中坡 */
        { 6, 9.0 },  /* 陡坡 */
        { 7, -3.5 }, /* 下坡 */
        { 7, 4.5 },  /* 中坡 */
        { 6, 7.5 },  /* 中陡 */
        { 6, 0.8 },  /* 高处平路台地 */
        { 6, 10.0 }, /* 最后一段陡坡 */
        { 3, -4.5 }, /* 下坡收尾 */
    };
    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
    double e = 326.0; /* 与骑行页当前海拔（R.elevation）对齐 */
    int k = 0;

    s_elev[0] = e;
    for (size_t p = 0; p < sizeof(plan) / sizeof(plan[0]); p++) {
        for (int i = 0; i < plan[p].n && k + 1 < ELEV_PROF_N; i++) {
            e += step * plan[p].pct / 100.0;
            s_elev[k + 1] = e;
            k++;
        }
    }
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        const double g = fabs(s_elev[i + 1] - s_elev[i]) / step * 100.0;

        s_elev_zone[i] = (g < ELEV_GRADE_FLAT) ? 0u
                       : (g < ELEV_GRADE_STEEP) ? 1u
                                                : 2u;
    }
}

/** 坡度档的填充色：0 中性灰 / 1 模式浅色 / 2 淡红。 */
static uint32_t elev_fill(uint8_t z)
{
    if (z == 1u) {
        return C_LIGHT[M_RIDE];
    }
    if (z == 2u) {
        return 0xE8CCC4u;
    }
    return C_LIGHT[3]; /* 中性灰（与“平路”语义一致） */
}

/** 坡度档的脊线色：0 灰 / 1 模式深色 / 2 红。 */
static uint32_t elev_ink(uint8_t z)
{
    if (z == 1u) {
        return C_DEEP[M_RIDE];
    }
    if (z == 2u) {
        return P_RED;
    }
    return P_TICK;
}

/** 把 60 点剖面烘焙到 RGB565 画布（照旧 UI 的 canvas bake）。
 * @param grid true 时画 3 条横向参考线（整页大图用）。 */
static void elev_canvas_paint(lv_obj_t *cv, int w, int h, bool grid)
{
    lv_layer_t layer;
    double mn = s_elev[0];
    double mx = s_elev[0];
    const int base = h - 1;
    const int top = grid ? 10 : 3;
    const int bot = base - top;

    for (int i = 1; i < ELEV_PROF_N; i++) {
        if (s_elev[i] < mn) mn = s_elev[i];
        if (s_elev[i] > mx) mx = s_elev[i];
    }
    if (mx - mn < 1.0) {
        mx = mn + 1.0;
    }

    lv_canvas_fill_bg(cv, lv_color_hex(P_PAPER), LV_OPA_COVER);
    lv_canvas_init_layer(cv, &layer);
    if (grid) {
        lv_draw_line_dsc_t gd;

        lv_draw_line_dsc_init(&gd);
        gd.color = lv_color_hex(P_CARD);
        gd.width = 1;
        gd.opa = LV_OPA_COVER;
        for (int k = 1; k <= 3; k++) {
            gd.p1.x = 0;
            gd.p1.y = top + (bot - top) * k / 4;
            gd.p2.x = w - 1;
            gd.p2.y = gd.p1.y;
            lv_draw_line(&layer, &gd);
        }
    }
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        const int x1 = (i * (w - 1)) / (ELEV_PROF_N - 1);
        const int x2 = ((i + 1) * (w - 1)) / (ELEV_PROF_N - 1);
        const int y1 = bot - (int)lround((s_elev[i] - mn) / (mx - mn) *
                                        (double)(bot - top));
        const int y2 = bot - (int)lround((s_elev[i + 1] - mn) / (mx - mn) *
                                         (double)(bot - top));
        const uint32_t fill = elev_fill(s_elev_zone[i]);
        const uint32_t ink = elev_ink(s_elev_zone[i]);
        lv_draw_triangle_dsc_t tri;
        lv_draw_line_dsc_t ld;

        lv_draw_triangle_dsc_init(&tri);
        tri.color = lv_color_hex(fill);
        tri.opa = LV_OPA_COVER;
        tri.grad.dir = LV_GRAD_DIR_NONE;
        tri.p[0].x = x1;
        tri.p[0].y = y1;
        tri.p[1].x = x2;
        tri.p[1].y = y2;
        tri.p[2].x = x2;
        tri.p[2].y = base;
        lv_draw_triangle(&layer, &tri);
        tri.p[0].x = x2;
        tri.p[0].y = base;
        tri.p[1].x = x1;
        tri.p[1].y = base;
        tri.p[2].x = x1;
        tri.p[2].y = y1;
        lv_draw_triangle(&layer, &tri);

        lv_draw_line_dsc_init(&ld);
        ld.color = lv_color_hex(ink);
        ld.width = 2;
        ld.opa = LV_OPA_COVER;
        ld.round_start = 1;
        ld.round_end = 1;
        ld.p1.x = x1;
        ld.p1.y = y1;
        ld.p2.x = x2;
        ld.p2.y = y2;
        lv_draw_line(&layer, &ld);
    }
    lv_canvas_finish_layer(cv, &layer);
}

/** 骑行页底部“前方海拔剖面”条：顶基线 + 右侧距离 + 2 px 当前位置。
 *  WP-HELM6：整条 274..315（42 px；WP-HELM5 是 276..315 = 40 px）。
 *  心率带收 2 px、四格上移 3 px 之后把空间还给剖面，画布高 26→28 px。 */
static void ride_elev_strip(void)
{
    lv_obj_t *cv;

    elev_profile_gen();
    (void)B(s_scr, 24, 274, 192, 1, P_HAIR, LV_OPA_COVER, 0); /* 顶部基线 */
    (void)LW(s_scr, "前方 2 km", PX_MICRO, P_MUTE, 120, 275, 96,
             LV_TEXT_ALIGN_RIGHT);
    /* 当前位置 = 剖面左端：2 px 竖线。 */
    (void)B(s_scr, 24, 288, 2, ELEV_CANVAS_H, P_INK, LV_OPA_COVER, 0);
    cv = lv_canvas_create(s_scr);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(cv, 26, 288);
    lv_canvas_set_buffer(cv, s_elev_cbuf, ELEV_CANVAS_W, ELEV_CANVAS_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, ELEV_CANVAS_W, ELEV_CANVAS_H);
    elev_canvas_paint(cv, ELEV_CANVAS_W, ELEV_CANVAS_H, false);
}

/* ── 第 11 屏「海拔」：整页剖面 + 当前坡度 / 累计爬升 / 最高点 ──────
 * 可选屏，`SIM_HELM_SCREEN=elevation` 直达（与 icons / iconopt 同类调试屏，
 * 不进十屏巡页，也不改导航页 KEY1 的既有行为）。 */
#define ELEV_BIG_W 190
#define ELEV_BIG_H 150
static uint8_t s_elev_big_cbuf[ELEV_BIG_W * ELEV_BIG_H * 2]
    __attribute__((aligned(4)));

/** 一列统计：11px 标签 + 22px 数值 + 11px 单位。 */
static void elev_stat(int x, const char *lab, const char *val,
                      const char *unit)
{
    L(s_scr, lab, PX_MICRO, P_MUTE, x, 236);
    (void)L(s_scr, val, PX_VALUE, P_INK, x, 250);
    L(s_scr, unit, PX_MICRO, P_MUTE, x + text_width(val, PX_VALUE) + 3, 261);
}

static void elev_build(void)
{
    lv_obj_t *cv;
    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
    double gain = 0;
    double mn;
    double mx;
    int peak = 0;
    char buf[32];

    d_bg(s_scr, P_PAPER);
    TOP(s_scr, "海拔", "前方 2 km");
    elev_profile_gen();
    mn = s_elev[0];
    mx = s_elev[0];
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        if (s_elev[i + 1] > s_elev[i]) {
            gain += s_elev[i + 1] - s_elev[i];
        }
    }
    for (int i = 1; i < ELEV_PROF_N; i++) {
        if (s_elev[i] < mn) mn = s_elev[i];
        if (s_elev[i] > mx) {
            mx = s_elev[i];
            peak = i;
        }
    }

    L(s_scr, "海拔 m", PX_MICRO, P_MUTE, 24, 40);
    snprintf(buf, sizeof(buf), "%d–%d m", (int)lround(mn), (int)lround(mx));
    LW(s_scr, buf, PX_MICRO, P_MUTE, 120, 40, 96, LV_TEXT_ALIGN_RIGHT);

    /* 当前位置竖线 + 大图（190×150）。 */
    (void)B(s_scr, 24, 56, 2, ELEV_BIG_H, P_INK, LV_OPA_COVER, 0);
    cv = lv_canvas_create(s_scr);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(cv, 26, 56);
    lv_canvas_set_buffer(cv, s_elev_big_cbuf, ELEV_BIG_W, ELEV_BIG_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, ELEV_BIG_W, ELEV_BIG_H);
    elev_canvas_paint(cv, ELEV_BIG_W, ELEV_BIG_H, true);

    /* 横轴：0 / 1 km / 2 km。 */
    (void)B(s_scr, 24, 210, 192, 1, P_HAIR, LV_OPA_COVER, 0);
    L(s_scr, "0", PX_MICRO, P_MUTE, 24, 212);
    LW(s_scr, "1 km", PX_MICRO, P_MUTE, 96, 212, 48, LV_TEXT_ALIGN_CENTER);
    LW(s_scr, "2 km", PX_MICRO, P_MUTE, 168, 212, 48, LV_TEXT_ALIGN_RIGHT);

    snprintf(buf, sizeof(buf), "%.1f",
             grade_val((s_elev[1] - s_elev[0]) / step * 100.0));
    elev_stat(24, "当前坡度", buf, grade_unit());
    snprintf(buf, sizeof(buf), "%d", (int)lround(gain));
    elev_stat(96, "累计爬升", buf, "m");
    snprintf(buf, sizeof(buf), "%d", (int)lround(mx));
    elev_stat(168, "最高点", buf, "m");
    snprintf(buf, sizeof(buf), "最高点在前方 %.1f km",
             (double)peak * step / 1000.0);
    LW(s_scr, buf, PX_MICRO, P_MUTE, 24, 286, 192, LV_TEXT_ALIGN_CENTER);
}

static void ride_refresh_dial(void)
{
    char buf[32];

    if (UR.arc == NULL) {
        return;
    }
    lv_arc_set_value(UR.arc, (int)lround(R.speed));
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.hero, buf);
    lv_obj_set_style_text_color(UR.hero,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.unit != NULL) {
        lv_label_set_text(UR.unit, unit_speed());
        lv_obj_set_style_text_color(UR.unit,
                                    lv_color_hex(R.paused ? P_TRACK : P_MUTE),
                                    0);
    }
    snprintf(buf, sizeof(buf), "%d", R.hr);
    if (UR.hr_val != NULL) {
        const int z = hr_zone(R.hr);
        const int bx0 = HR_BAR_X0 + (z - 1) * HR_BAR_W / 5;
        const int bx1 = HR_BAR_X0 + z * HR_BAR_W / 5;

        lv_label_set_text(UR.hr_val, buf);
        /* 单位紧跟数值（advance 宽度 + 4 px ≈ 6 px 墨迹间隙），不再右对齐。 */
        lv_obj_set_x(UR.hr_unit, 24 + text_width(buf, PX_VALUE) + 4);
        /* 分区 = 指针位置 + 当前格 1px 描边；格子底色不变。 */
        lv_obj_set_x(UR.hr_ptr, hr_bar_x(R.hr));
        lv_obj_set_pos(UR.hr_sel, bx0, HR_BAR_Y);
        lv_obj_set_size(UR.hr_sel, bx1 - bx0, HR_BAR_H);
        lv_obj_set_style_border_color(UR.hr_sel,
                                      lv_color_hex(HR_ZONE_LINE[z - 1]), 0);
        {
            char b[48];
            int avg;
            int peak;

            hr_hist_stats(&avg, &peak);
            snprintf(b, sizeof(b), "均 %d · 峰 %d", avg, peak);
            lv_label_set_text(UR.hr_stats, b);
        }
    }
    {
        int x = SPD_BAR_X0 + (int)lround((double)SPD_BAR_W * R.speed / 60.0) - 1;

        if (x < SPD_BAR_X0 + 1) x = SPD_BAR_X0 + 1;
        if (x > SPD_BAR_X0 + SPD_BAR_W - 4) x = SPD_BAR_X0 + SPD_BAR_W - 4;
        lv_obj_set_x(UR.cursor, x);
    }
    {
        const char *vals[4];
        char b0[24], b1[24], b2[24], b3[24];

        /* 表盘页固定四格（里程 / 时间 / 踏频 / 海拔）；其它数据在数字页。 */
        snprintf(b0, sizeof(b0), "%.1f", conv_dist(R.dist_km));
        snprintf(b1, sizeof(b1), "%u:%02u",
                 (unsigned)(R.elapsed_s / 60),
                 (unsigned)(R.elapsed_s % 60));

                 (unsigned)(R.elapsed_s % 60));
        snprintf(b2, sizeof(b2), "%d", R.cadence);
        snprintf(b3, sizeof(b3), "%d", R.elevation);
        vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        for (int i = 0; i < 4; i++) {
            lv_label_set_text(UR.metrics[i], vals[i]);
        }
    }
}

/* 第 2 页（纯数字栅格）：8 格值，等宽右对齐；暂停时数字退灰。 */
static void ride_refresh_grid(void)
{
    char b[8][24];
    const uint32_t ink = R.paused ? P_TRACK : P_INK;

    if (UR.gv[0] == NULL) {
        return;
    }
    snprintf(b[0], sizeof(b[0]), "%.1f", conv_speed(R.speed));
    snprintf(b[1], sizeof(b[1]), "%.1f", conv_speed(R.avg));
    snprintf(b[2], sizeof(b[2]), "%.1f", conv_dist(R.dist_km));
    snprintf(b[3], sizeof(b[3]), "%u:%02u",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
    snprintf(b[4], sizeof(b[4]), "%d", R.hr);
    snprintf(b[5], sizeof(b[5]), "%d", R.cadence);
    snprintf(b[6], sizeof(b[6]), "%d", R.elevation);
    snprintf(b[7], sizeof(b[7]), "%+.1f", grade_val(R.grade));
    for (int i = 0; i < 8; i++) {
        lv_label_set_text(UR.gv[i], b[i]);
        lv_obj_set_style_text_color(UR.gv[i], lv_color_hex(ink), 0);
    }
}

/* 第 3 页（全屏地图）：速度大字 + 右半块（转向 / 本次骑行时长）+ 已骑里程。 */
static void ride_refresh_map(void)
{
    char buf[32];

    if (UR.map_speed == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.map_speed, buf);
    lv_obj_set_style_text_color(UR.map_speed,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.map_unit != NULL) {
        lv_label_set_text(UR.map_unit, unit_speed());
        /* 单位固定在数值下方一行（卡内 14,44），不随位数右移。 */
    }
    if (UR.map_turn != NULL) {
        if (s_nav_active) {
            const int m = 480 - (int)(R.elapsed_s * 10) % 480;

            snprintf(buf, sizeof(buf), "%d m", ((m <= 0 ? 480 : m) / 10) * 10);
            lv_label_set_text(UR.map_turn, buf);
            lv_label_set_text(UR.map_turn_sub, NAV_TURNS[s_nav_turn % 4]);
        } else {
            /* 未导航：右半块显示本次骑行时长（与数字页同一格式）。 */
            snprintf(buf, sizeof(buf), "%u:%02u",
                     (unsigned)(R.elapsed_s / 60),
                     (unsigned)(R.elapsed_s % 60));
            lv_label_set_text(UR.map_turn, buf);
            lv_label_set_text(UR.map_turn_sub, "本次骑行");
        }
    }
    if (UR.map_dist != NULL) {
        snprintf(buf, sizeof(buf), "已骑 %.1f %s", conv_dist(R.dist_km),
                 unit_dist());
        lv_label_set_text(UR.map_dist, buf);
    }
}

static void ride_refresh(void)
{
    if (s_ride_page == 1) {
        ride_refresh_grid();
    } else if (s_ride_page == 2) {
        ride_refresh_map();
    } else {
        ride_refresh_dial();
    }
}

static void ride_page_types(void)
{
    char lab[4][24];

    snprintf(lab[0], sizeof(lab[0]), "里程 %s", unit_dist());
    snprintf(lab[1], sizeof(lab[1]), "时间");
    snprintf(lab[2], sizeof(lab[2]), "踏频 rpm");
    snprintf(lab[3], sizeof(lab[3]), "海拔 m");
    for (int i = 0; i < 4; i++) {
        lv_obj_t *parent = lv_obj_get_parent(UR.metrics[i]);

        lv_label_set_text(lv_obj_get_child(parent, 0), lab[i]);
    }
}

/* ── 共用状态栏（环形页 + 三个骑行页同一套；y=0..24，内容从 y≥24）──
 *

static void ride_page_dots(void)
{
    for (int i = 0; i < 3; i++) {
        (void)B(s_scr, 12 + i * 10, 26, 7, 7,
                i == s_ride_page ? C_DEEP[M_RIDE] : P_TRACK,
                LV_OPA_COVER, 3);
    }
}

/* 第 1 页：270° 仪表 + 大时速（原骑行页，保留）。 */
static void ride_build_dial(void)
{
    lv_obj_t *arc;
    lv_obj_t *hero_box;

    /* 270° 仪表：中心 (120,106)、d=152、7px（与盘面收缩后的几何对位）。 */
    arc = lv_arc_create(s_scr);
    lv_obj_set_size(arc, 152, 152);
    lv_obj_set_pos(arc, 44, 30);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(P_TRACK), LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_DEEP[M_RIDE]),
                               LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(arc, lv_color_hex(P_INK), LV_PART_KNOB);
    lv_obj_set_style_bg_opa(arc, LV_OPA_COVER, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 3, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_range(arc, 0, 60);
    lv_arc_set_value(arc, (int)lround(R.speed));
    UR.arc = arc;

    /* 刻度外径 82：12 点方向墨迹正好落在 y=24（状态栏占 0..23），再加大
     * 就会穿出发丝线；这是几何约束，不是随手取的数。 */
    for (int i = 0; i < 7; i++) {
        lv_point_precise_t pts[2];
        const double a = (double)(225 + i * 45) * DEG2RAD;

        pts[0].x = 120 + (int)lround(sin(a) * 78);
        pts[0].y = 106 - (int)lround(cos(a) * 78);
        pts[1].x = 120 + (int)lround(sin(a) * 82);
        pts[1].y = 106 - (int)lround(cos(a) * 82);
        (void)LINE(s_scr, pts, 2, 1, P_TICK);
    }

    /* hero：容器整体做 0→100% 淡入（ANIMATION #3 的阶段 C）。 */
    hero_box = lv_obj_create(s_scr);
    lv_obj_remove_style_all(hero_box);
    lv_obj_set_pos(hero_box, 40, 64);
    lv_obj_set_size(hero_box, 160, 72);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_CLICKABLE);
    UR.hero_box = hero_box;
    {
        lv_obj_t *stack = d_stack(hero_box, 0, 0, 160, 56,
                                  LV_FLEX_ALIGN_CENTER, 0);

        UR.hero = lv_label_create(stack);
        lv_obj_set_style_text_font(UR.hero, F(PX_HERO), 0);
        lv_obj_set_style_text_color(UR.hero,
                                    lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    }
    UR.unit = LW(hero_box, unit_speed(), PX_SMALL, P_MUTE, 0, 56, 160,
                 LV_TEXT_ALIGN_CENTER);

    /* 速度带（WP-HELM6 第二步）：满内容宽 x=24..216（w=192），与四格/剖面同轴。
     * `速度` 文字删掉：上方 hero “22.0 km/h” 已经说明量纲，再写一遍是冗余；
     * 删掉后这一行只剩“带 + 刻度”，两条带结构完全对称（值在上、带在下）。
     * 三段 96/48/48 = 0-30/30-45/45-60；刻度 0/30/60 仍在带内。 */
    {
        const int x0 = SPD_BAR_X0, w = SPD_BAR_W;
        const int w1 = w / 2, w2 = w / 4;

        (void)B(s_scr, x0, SPD_BAR_Y, w1, SPD_BAR_H, C_LIGHT[M_NAV],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, w2, SPD_BAR_H, C_LIGHT[M_RIDE],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, w2, SPD_BAR_H,
                C_LIGHT[M_RECORD], LV_OPA_COVER, 0);
        (void)B(s_scr, x0, SPD_BAR_Y, w1, 2, C_DEEP[M_NAV], LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, w2, 2, C_DEEP[M_RIDE],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, w2, 2, C_DEEP[M_RECORD],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, SPD_BAR_Y, 1, SPD_BAR_H, P_INK, LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, SPD_BAR_Y, 1, SPD_BAR_H, P_INK,
                LV_OPA_COVER, 0);
        {
            char b[8];

            L(s_scr, "0", PX_MICRO, P_INK, x0 + 4, SPD_BAR_Y + 2);
            snprintf(b, sizeof(b), "%.0f", conv_speed(30.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w1 + 3, SPD_BAR_Y + 2);
            snprintf(b, sizeof(b), "%.0f", conv_speed(60.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w - 16, SPD_BAR_Y + 2);
        }
        UR.cursor = B(s_scr, x0 + (int)lround(w * R.speed / 60.0) - 1,
                      SPD_BAR_Y - 1, BAR_PTR_W, BAR_PTR_H, P_INK,
                      LV_OPA_COVER, 1);
    }

    /* 心率行（WP-HELM6 第二步）：「心率 Z4」标签删掉，只留值 + 单位。
     *   第 1 行 “148” 22px，左对齐 x=24；单位 “bpm” 12px 紧跟其后
     *          （x 由 ride_refresh 按 advance 宽度重算，不再右对齐 216）；
     *   第 2 行 5 分区色带 x=24,w=192,y=223,h=18（满内容宽，与四格/剖面同轴）；
     *          当前分区 = 2px 竖线指针（与速度指针同规格）+ 当前格 1px 深色
     *          描边；格子底色只有浅色阶梯，没有整格深色填充。
     * 竖直：速度带 184..201、值墨迹 204..220、色带 223..240；比 WP-HELM5
     *       （色带 224..243、高 20）上移 1 px、矮 2 px，收回的 3 px 给了剖面。 */
    {
        const int x0 = HR_BAR_X0, w = HR_BAR_W;

        UR.hr_val = L(s_scr, "148", PX_VALUE, P_INK, 24, 199);
        UR.hr_unit = L(s_scr, "bpm", PX_SMALL, P_MUTE, 64, 206);
        /* 右侧次级统计「均 133 · 峰 148」：11 px 次要色，盒 120..215
         * 右对齐 216，与 148 同一行；文本由 ride_refresh 现算填入。 */
        UR.hr_stats = LW(s_scr, "", PX_MICRO, P_MUTE, 120, 206, 96,
                         LV_TEXT_ALIGN_RIGHT);
        for (int i = 0; i < 5; i++) {
            const int bx = x0 + i * w / 5;
            const int bw = x0 + (i + 1) * w / 5 - bx;

            UR.hr[i] = B(s_scr, bx, HR_BAR_Y, bw, HR_BAR_H, HR_ZONE_LIGHT[i],
                         LV_OPA_COVER, 0);
        }
        for (int i = 1; i < 5; i++) {
            (void)B(s_scr, x0 + i * w / 5, HR_BAR_Y, 1, HR_BAR_H, P_TICK,
                    LV_OPA_COVER, 0);
        }
        /* 当前格：只有 1px 边、没有底（bg 透明），所以不会变成深色块。 */
        UR.hr_sel = lv_obj_create(s_scr);
        lv_obj_remove_style_all(UR.hr_sel);
        lv_obj_set_pos(UR.hr_sel, x0 + 3 * w / 5, HR_BAR_Y);
        lv_obj_set_size(UR.hr_sel, x0 + 4 * w / 5 - (x0 + 3 * w / 5),
                        HR_BAR_H);
        lv_obj_remove_flag(UR.hr_sel, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_remove_flag(UR.hr_sel, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_set_style_bg_opa(UR.hr_sel, LV_OPA_TRANSP, 0);
        lv_obj_set_style_radius(UR.hr_sel, 0, 0);
        lv_obj_set_style_border_width(UR.hr_sel, 1, 0);
        lv_obj_set_style_border_opa(UR.hr_sel, LV_OPA_COVER, 0);
        lv_obj_set_style_border_color(UR.hr_sel,
                                      lv_color_hex(HR_ZONE_LINE[3]), 0);
        /* 指针最后建、压在最上层：落在格线上也读得清。 */
        UR.hr_ptr = B(s_scr, hr_bar_x(R.hr), BAR_PTR_Y, BAR_PTR_W, BAR_PTR_H,
                      P_INK, LV_OPA_COVER, 1);
    }

    /* 4 个指标（KEY1 短按切页，0ms 硬切）。WP-HELM6：心率带高 20→18，
     * 整行从 y=245 上移到 y=242（盒高 30、盒内间距 12 都不变），
     * 墨迹 244..268；给底部海拔剖面留 274..315（42 px）。字号/文案/列宽不变。 */
    {
        static const int cx[4] = { 48, 96, 144, 192 };

        for (int i = 0; i < 4; i++) {
            lv_obj_t *box = lv_obj_create(s_scr);

            lv_obj_remove_style_all(box);
            lv_obj_set_pos(box, cx[i] - 30, 242);
            lv_obj_set_size(box, 60, 30);
            lv_obj_remove_flag(box, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
            {
                lv_obj_t *lab = LW(box, "", PX_MICRO, P_MUTE, 0, 0, 60,
                                   LV_TEXT_ALIGN_CENTER);
                lv_obj_t *val = LW(box, "", PX_BODY, P_INK, 0, 12, 60,
                                   LV_TEXT_ALIGN_CENTER);

                (void)lab;
                UR.metrics[i] = val;
            }
        }
    }
    ride_elev_strip();
    ride_page_types();
    ride_refresh();
}

