/** @brief lv_color_t → 0xRRGGBB（本表内部用 24 位值，helm_color() 再量化）。 */
static uint32_t pal_hex(lv_color_t c)
{
    return ((uint32_t)c.red << 16) | ((uint32_t)c.green << 8) | (uint32_t)c.blue;
}

