    lv_obj_clear_flag(s_sh.cell_rail[idx], LV_OBJ_FLAG_CLICKABLE);

    col = lv_obj_create(r);
    lv_obj_remove_style_all(col);
    helm_grow_x(col);
    lv_obj_set_height(col, lv_pct(100));
