/** @brief 心率分区（WP 口径 Z1..Z5：<100 / 100-119 / 120-139 / 140-159 / ≥160）。 */
static int helm_dial_hr_zone(int bpm)
{
    if (bpm < 100) {
        return 1;
    }
    if (bpm < 120) {
        return 2;
    }
    if (bpm < 140) {
        return 3;
    }
    if (bpm < 160) {
        return 4;
    }
    return 5;
}

/** @brief 心率指针落点（2px 宽，落在 x..x+1）：五格等宽、格内按区间线性细分。 */
static int helm_dial_hr_x(int bpm)
{
    int32_t u;

    if (bpm < 60) {
        bpm = 60;
    }
    if (bpm > 200) {
        bpm = 200;
    }
    if (bpm < 100) {
        u = (int32_t)(bpm - 60) * 1000 / 40;
    } else if (bpm < 120) {
        u = 1000 + (int32_t)(bpm - 100) * 1000 / 20;
    } else if (bpm < 140) {
        u = 2000 + (int32_t)(bpm - 120) * 1000 / 20;
    } else if (bpm < 160) {
        u = 3000 + (int32_t)(bpm - 140) * 1000 / 20;
    } else {
        u = 4000 + (int32_t)(bpm - 160) * 1000 / 40;
    }
    {
        int x = HELM_HR_BAR_X +
                (int)(((int32_t)HELM_HR_BAR_W * u + 2500) / 5000) - 1;

        if (x < HELM_HR_BAR_X) {
            x = HELM_HR_BAR_X;
        }
        if (x > HELM_HR_BAR_X + HELM_HR_BAR_W - HELM_BAR_PTR_W) {
            x = HELM_HR_BAR_X + HELM_HR_BAR_W - HELM_BAR_PTR_W;
        }
        return x;
    }
}

