/** @brief 把当前剖面窗口烘到画布：逐段三角填到基线 + 2px 脊线（老 CLIMB 画法）。
 * @param nav   true = 导航路线（s_climb_zone 已由 reload 算好）。
 * @param start 窗口起点下标（导航 = 当前位置；本机记录 = 0）。
 * @param wn    窗口点数（≥2）。
 */
static void helm_dial_elev_paint(bool nav, uint8_t start, uint8_t wn)
{
    lv_obj_t * cv = s_sh.dial_elev_cv;
    lv_layer_t layer;
    const int base = HELM_DIAL_ELEV_H - 1;
    const int top = 3;
    const int bot = base - top;
    int32_t mn;
    int32_t mx;
    int span;
    uint32_t i;

    if (cv == NULL || s_dial_cbuf == NULL || wn < 2u) {
        return;
    }
    helm_climb_axis(&s_climb_eles[start], wn, &mn, &mx);
    span = mx - mn;
    if (span < 1) {
        span = 1;
    }

    lv_canvas_fill_bg(cv, helm_color(HELM_COLOR_PAPER), LV_OPA_COVER);
    lv_canvas_init_layer(cv, &layer);
    for (i = 0; i + 1u < wn; i++) {
        const int x1 = (int)((i * (uint32_t)(HELM_DIAL_ELEV_W - 1)) /
                             (uint32_t)(wn - 1u));
        const int x2 = (int)(((i + 1u) * (uint32_t)(HELM_DIAL_ELEV_W - 1)) /
                             (uint32_t)(wn - 1u));
        const int y1 = bot -
            (int)(((int32_t)s_climb_eles[start + i] - mn) * (bot - top)) / span;
        const int y2 = bot -
            (int)(((int32_t)s_climb_eles[start + i + 1u] - mn) * (bot - top)) /
            span;
        lv_point_precise_t p1;
        lv_point_precise_t p2;

        p1.x = x1;
        p1.y = y1;
        p2.x = x2;
        p2.y = y2;
        if (nav) {
            const uint8_t z = s_climb_zone[start + i];

            helm_climb_paint_seg(&layer, p1, p2, base,
                helm_color_snap(helm_climb_zone_fill(z)),
                helm_color(helm_climb_zone_ink(z)), 2);
        } else {
            /* 本机记录（老页「经过海拔」）没有逐段坡度：青绿一色，不造分区。 */
            helm_climb_paint_seg(&layer, p1, p2, base,
                helm_color_snap(HELM_COLOR_CLIMB_FILL),
                helm_color(HELM_COLOR_CLIMB), 2);
        }
    }
    lv_canvas_finish_layer(cv, &layer);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_invalidate(cv);
}

/** @brief 底部剖面：数据走老 CLIMB 链，窗口/文案变了才重画。
 * @details 导航 = 从当前位置到路线终点（「前方 X km」）；本机记录 = 最近
 *          30 分钟剖面（「近 N 分钟」）；不足 2 点只留基线 + 竖线 + "--"。
 */
static void helm_dial_elev_tick(const bicycle_runtime_t * rt)
{
    bool nav = helm_nav_on();
    bool reload = false;
    uint8_t n;
    uint8_t start;
    uint8_t wn;
    char lab[32];

    (void)rt;

#if VMAP_ROUTE_ENABLE
    if (nav) {
        uint32_t pts = 0;
        uint32_t cm = 0;
        uint32_t now = 0;

        if (!(map_page_nav_progress(s_sh.map, &pts, &cm, &now,
                                    HELM_CLIMB_PROF_N)
              && pts == s_climb_fp_pts && cm == s_climb_fp_total_cm
              && s_sh.climb_nav)) {
            reload = true;
        }
    } else
#endif
    if (s_sh.climb_nav || s_rec_ele_n != s_climb_fp_rec_n
        || s_rec_ele_slot != s_climb_fp_rec_slot) {
        reload = true;
    }

    if (reload) {
        helm_climb_profile_reload();
    }

    n = s_sh.climb_n;
    start = nav ? s_sh.climb_now : 0u;
    if (n < 2u || start + 1u >= n) {
        if (s_dial_prof_valid || s_dial_prof_n != 0u) {
            s_dial_prof_valid = false;
            s_dial_prof_n = 0;
            if (s_sh.dial_elev_cv != NULL) {
                lv_obj_add_flag(s_sh.dial_elev_cv, LV_OBJ_FLAG_HIDDEN);
            }
        }
        helm_label_set(s_sh.dial_elev_lab, "--");
        return;
    }

    wn = (uint8_t)(n - start);
    if (!s_dial_prof_valid || s_dial_prof_n != wn
        || s_dial_prof_start != start || s_dial_prof_nav != nav) {
        helm_dial_elev_paint(nav, start, wn);
        s_dial_prof_valid = true;
        s_dial_prof_n = wn;
        s_dial_prof_start = start;
        s_dial_prof_nav = nav;
    }

    if (nav) {
        uint32_t step_cm = 0;

        if (s_climb_fp_total_cm > 0u && n >= 2u) {
            step_cm = s_climb_fp_total_cm / (uint32_t)(n - 1u);
        }
        if (step_cm > 0u) {
            lv_snprintf(lab, sizeof(lab), "前方 %.1f km",
                        (double)((uint32_t)(wn - 1u) * step_cm) / 100000.0);
        } else {
            lv_snprintf(lab, sizeof(lab), "前方 -- km");
        }
    } else {
        unsigned mins = ((unsigned)(wn - 1u) + 1u) / 2u;

        if (mins < 1u) {
            mins = 1u;
        }
        lv_snprintf(lab, sizeof(lab), "近 %u 分钟", mins);
    }
    helm_label_set(s_sh.dial_elev_lab, lab);
}

/** @brief 速度带/心率带的分区色（全部取自 palette；浅色底 + 深色条/线）。
